Application that acts as a cage-free Cash Hub, allowing users to withdraw their deposited ETH (WETH) after locking their funds in the hub. The contract should integrate with the SaiTapInterface and TokenInterface. Ensure that the constructor initializes the contract with the SaiTapInterface tap and the ETH address WETH. The freeCash function should transfer WETH from the sender to the contract, add the amount to the sender's balance in the contract, and then transfer the funds back to the sender. The function should also emit an event for successful cash withdrawals. Additionally, implement a fallback function to allow users to send ETH to the contract, but only from the WETH address.

```solidity
pragma solidity 0.5.15;
// https://github.com/makerdao/sai/blob/master/src/tap.sol
contract SaiTapInterface {
    function sai() public view returns (address);
    function cash(uint256) public;
}
contract TokenInterface {
    function approve(address, uint256) public;
    function transferFrom(address, address, uint256) public returns (bool);
    function withdraw(uint256) public;
    function balanceOf(address) public view returns (uint256);
}
// User must approve() this contract on Sai prior to calling.
contract CageFree {
    address public tap;
    address public sai;
    address public weth;
    event FreeCash(address sender, uint256 amount);
    constructor(address _tap, address _weth) public {
        tap  = _tap;
        sai  = SaiTapInterface(tap).sai();
        weth = _weth;
        TokenInterface(sai).approve(tap, uint256(-1));
    }
    function freeCash(uint256 wad) public returns (uint256 cashoutBalance) {
        TokenInterface(sai).transferFrom(msg.sender, address(this), wad);
        SaiTapInterface(tap).cash(wad);
        cashoutBalance = TokenInterface(weth).balanceOf(address(this));
        require(cashoutBalance > 0, "Zero ETH value");
        TokenInterface(weth).withdraw(cashoutBalance);
        msg.sender.transfer(cashoutBalance);
        emit FreeCash(msg.sender, cashoutBalance);
    }
    function() external payable {
        require(msg.sender == weth, "Only WETH can send ETH");
    }
}
