        _refreshWeight(msg.sender);
        Ballot storage b = ballots[msg.sender];
        uint256 amount = b.rewards;
        require(amount > 0, "nothing to claim");
        b.rewards = 0;
        require(token.transfer(msg.sender, amount), "transfer failed");
