        uint256 totalStaked = 0;
        for (uint256 i = 1; i <= 4; i++) {
            totalStaked += pools[i].totalStaked;
        }
        return totalStaked;
    }
    function getCurrentPoolAPY(uint256 poolId) public view returns (uint256) {
        require(poolId >= 1 && poolId <= 4, "Invalid pool ID");
