Program that allows for simulating a transaction by executing a delegate call to another contract. The smart contract should include an immutable address for the accessor singleton and a restricted modifier to ensure that the contract is only called via delegate call. The simulate function should accept four parameters: the destination address, a value to be sent, an optional data parameter, and an operation enum. The function should also provide an estimate of the gas consumption and return the success of the execution and any return data.

```solidity
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity >=0.7.0 <0.9.0;
import "../base/Executor.sol";
/// @author Richard Meissner - <richard@gnosis.pm>
contract SimulateTxAccessor is Executor {
    address private immutable accessorSingleton;
    constructor() {
        accessorSingleton = address(this);
    }
    modifier onlyDelegateCall() {
        require(address(this) != accessorSingleton, "SimulateTxAccessor should only be called via delegatecall");
        _;
    }
    function simulate(address to,
        uint256 value,
        bytes calldata data,
        Enum.Operation operation)
        external
        onlyDelegateCall()
        returns (uint256 estimate,
            bool success,
            bytes memory returnData)
    {
        uint256 startGas = gasleft();
        success = execute(to, value, data, operation, gasleft());
        estimate = startGas - gasleft();
        // solhint-disable-next-line no-inline-assembly
        assembly {
            // Load free memory location
            let ptr := mload(0x40)
            // We allocate memory for the return data by setting the free memory location to
            // current free memory location + data size + 32 bytes for data size value
            mstore(0x40, add(ptr, add(returndatasize(), 0x20)))
            // Store the size
            mstore(ptr, returndatasize())
            // Store the data
            returndatacopy(add(ptr, 0x20), 0, returndatasize())
            // Point the return data to the correct memory location
            returnData := ptr
        }
    }
}
