        ISolidlyPair _pair,
        IVelodromePairFactory _factory) {
        factory = _factory;
        pair = _pair;
        router = _router;
        (address _token0, address _token1) = _pair.tokens();
        IERC20(_token0).approve(address(_router), type(uint256).max);
