Web3 utility that implements OvnMath library functions for calculating absolute values, adding or subtracting basis points from a base amount, and reversing these operations. The contract should include the provided OvnMath library and implement the following functions: abs(), addBasisPoints(), reverseAddBasisPoints(), subBasisPoints(), and reverseSubBasisPoints(). Ensure the functions are internally pure, meaning they do not modify external state and always return the same output given the same inputs. Implement variable declarations and function definitions following the provided code fragment. The contract should be compatible with Solidity versions 0.8.0 to 0.8.9.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;
library OvnMath {
    uint256 constant BASIS_DENOMINATOR = 10 ** 4;
    function abs(uint256 x, uint256 y) internal pure returns (uint256) {
        return (x > y) ? (x - y) : (y - x);
    }
    function addBasisPoints(uint256 amount, uint256 basisPoints) internal pure returns (uint256) {
        return amount * (BASIS_DENOMINATOR + basisPoints) / BASIS_DENOMINATOR;
    }
    function reverseAddBasisPoints(uint256 amount, uint256 basisPoints) internal pure returns (uint256) {
        return amount * BASIS_DENOMINATOR / (BASIS_DENOMINATOR + basisPoints);
    }
    function subBasisPoints(uint256 amount, uint256 basisPoints) internal pure returns (uint256) {
        return amount * (BASIS_DENOMINATOR - basisPoints) / BASIS_DENOMINATOR;
    }
    function reverseSubBasisPoints(uint256 amount, uint256 basisPoints) internal pure returns (uint256) {
        return amount * BASIS_DENOMINATOR / (BASIS_DENOMINATOR - basisPoints);
    }
}
