contract ProxyData {
  address implementation_;
  address public admin;
  constructor() {
    admin = msg.sender;
  }
  modifier onlyAdmin() {
    require(msg.sender == admin);
    _;
  }
  function transferOwnership(address newOwner) external {
    require(msg.sender == admin);
