Mechanism named OxDexFactory that extends the IOxDexFactory interface. The contract must have the following functions: setFeeTo() to update the feeTo address, setFeeToSetter() to update the feeToSetter address, and createPair() to create a new pair of tokens. The contract should also have a constructor to set the feeToSetter address and a mapping to keep track of all pairs. The createPair() function should check for duplicate pairs and handle the creation of a new pair by deploying a new OxDexPair contract. Implement the necessary error handling and emit events for the PairCreated event.

```solidity
pragma solidity =0.5.16;
import './interfaces/IOxDexFactory.sol';
import './OxDexPair.sol';
contract OxDexFactory is IOxDexFactory {
    address public feeTo;
    address public feeToSetter;
    mapping(address => mapping(address => address)) public getPair;
    address[] public allPairs;
    event PairCreated(address indexed token0, address indexed token1, address pair, uint256);
    constructor(address _feeToSetter) public {
        feeToSetter = _feeToSetter;
    }
    function allPairsLength() external view returns (uint256) {
        return allPairs.length;
    }
    function createPair(address tokenA, address tokenB) external returns (address pair) {
        require(tokenA != tokenB, 'OxDex: IDENTICAL_ADDRESSES');
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), 'OxDex: ZERO_ADDRESS');
        require(getPair[token0][token1] == address(0), 'OxDex: PAIR_EXISTS'); // single check is sufficient
        bytes memory bytecode = type(OxDexPair).creationCode;
        bytes32 salt = keccak256(abi.encodePacked(token0, token1));
        assembly {
            pair := create2(0, add(bytecode, 32), mload(bytecode), salt)
        }
        IOxDexPair(pair).initialize(token0, token1);
        getPair[token0][token1] = pair;
        getPair[token1][token0] = pair; // populate mapping in the reverse direction
        allPairs.push(pair);
        emit PairCreated(token0, token1, pair, allPairs.length);
    }
    function setFeeTo(address _feeTo) external {
        require(msg.sender == feeToSetter, 'OxDex: FORBIDDEN');
        feeTo = _feeTo;
    }
    function setFeeToSetter(address _feeToSetter) external {
        require(msg.sender == feeToSetter, 'OxDex: FORBIDDEN');
        feeToSetter = _feeToSetter;
    }
}
