Outline a component that extends the provided library HitchensUnorderedAddressSetLib. The contract should inherit from the Set struct and provide additional functions to manipulate the set. Specifically, add ameerFind, to search and optionally remove an address from the set, and add address to the set if it does not already exist. Ensure that the contract enforces the set's integrity by checking for empty keys, 0x0 addresses and addresses that do not exist in the set. Implement transactional integrity by including error messages and requiring that the address to be removed does not exist in the set. Additionally, implement get addressAt method to retrieve an address at a specified index.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.6.0;
library HitchensUnorderedAddressSetLib {
    struct Set {
        mapping(address => uint) keyPointers;
        address[] keyList;
    }
    function insert(Set storage self, address key) internal {
        require(key != address(0), "UnorderedKeySet(100) - Key cannot be 0x0");
        require(!exists(self, key), "UnorderedAddressSet(101) - Address (key) already exists in the set.");
        self.keyList.push(key);
        self.keyPointers[key] = self.keyList.length - 1;
    }
    function remove(Set storage self, address key) internal {
        require(exists(self, key), "UnorderedKeySet(102) - Address (key) does not exist in the set.");
        address keyToMove = self.keyList[count(self)-1];
        uint rowToReplace = self.keyPointers[key];
        self.keyPointers[keyToMove] = rowToReplace;
        self.keyList[rowToReplace] = keyToMove;
        delete self.keyPointers[key];
        self.keyList.pop();
    }
    function count(Set storage self) internal view returns(uint) {
        return(self.keyList.length);
    }
    function exists(Set storage self, address key) internal view returns(bool) {
        if(self.keyList.length == 0) return false;
        return self.keyList[self.keyPointers[key]] == key;
    }
    function keyAtIndex(Set storage self, uint index) internal view returns(address) {
        return self.keyList[index];
    }
}
