Construct a module that acts as a proxy for a beacon, allowing it to interact with multiple beacon implementations. The contract should have a constructor that takes in the beacon address and optional data. It should also have functions for setting and retrieving the beacon slot value, as well as retrieving the beacon implementation. The contract should override the _implementation function to return the current beacon implementation, and implement a function to set the beacon address and data.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity >=0.6.0 <0.8.0;
import "./Proxy.sol";
import "./IBeacon.sol";
import "../lib/Address.sol";
contract BeaconProxy is Proxy {
    bytes32 private constant _BEACON_SLOT = 0xa3f0ad74e5423aebfd80d3ef4346578335a9a72aeaee59ff6cb3582b35133d50;
    constructor(address beacon, bytes memory data) public payable {
        assert(_BEACON_SLOT == bytes32(uint256(keccak256("eip1967.proxy.beacon")) - 1));
        _setBeacon(beacon, data);
    }
    function _beacon() internal view virtual returns (address beacon) {
        bytes32 slot = _BEACON_SLOT;
        // solhint-disable-next-line no-inline-assembly
        assembly {
            beacon := sload(slot)
        }
    }
    function _implementation() internal view virtual override returns (address) {
        return IBeacon(_beacon()).implementation();
    }
    function _setBeacon(address beacon, bytes memory data) internal virtual {
        require(Address.isContract(beacon),
            "BeaconProxy: beacon is not a contract");
        require(Address.isContract(IBeacon(beacon).implementation()),
            "BeaconProxy: beacon implementation is not a contract");
        bytes32 slot = _BEACON_SLOT;
        // solhint-disable-next-line no-inline-assembly
        assembly {
            sstore(slot, beacon)
        }
        if (data.length > 0) {
            Address.functionDelegateCall(_implementation(), data, "BeaconProxy: function call failed");
        }
    }
}
