Format a software that allows for the sale of kitten NFTs. The contract should have a function to transfer the NFT from the owner to the buyer, and an internal function to update the remaining NFTs for sale. The function that initiates the sale should verify the input value to ensure it meets specific requirements (e.g., 100 finney or greater). The same function should also perform calculations based on the input value to determine the correct amount of kitten NFTs to be sold. The smart contract should also include a getter function to retrieve the total NFTs sold, and an event function to emit details of each sale. Additionally, implement an emergency stop functionality to prevent further sales if necessary.

```solidity
pragma solidity ^0.4.13;
contract KittenCoin {
    function transferFrom(address _from, address _to, uint256 _value) public returns (bool) {}
    function allowance(address owner, address spender) public constant returns (uint256) {}
}
contract KittenSale {
    KittenCoin public _kittenContract;
    address public _kittenOwner;
    uint256 public totalContributions;
    uint256 public kittensSold;
    uint256 public kittensRemainingForSale;
    function KittenSale () {
        address c = 0xac2BD14654BBf22F9d8f20c7b3a70e376d3436B4; // set Kitten Coin contract address
        _kittenContract = KittenCoin(c); 
        _kittenOwner = msg.sender;
        totalContributions = 0;
        kittensSold = 0;
        kittensRemainingForSale = 0; // set to 0 first as allowance to contract can't be set yet
    }
    function () payable {
        require(msg.value > 0);
        uint256 contribution = msg.value;
        if (msg.value >= 100 finney) {
            if (msg.value >= 1 ether) {
                contribution /= 6666;
            } else {
                contribution /= 8333;
            }
        } else {
            contribution /= 10000;
        }
        require(kittensRemainingForSale >= contribution);
        totalContributions += msg.value;
        kittensSold += contribution;
        _kittenContract.transferFrom(_kittenOwner, msg.sender, contribution);
        _kittenOwner.transfer(msg.value);
        updateKittensRemainingForSale();
    }
    function updateKittensRemainingForSale () {
        kittensRemainingForSale = _kittenContract.allowance(_kittenOwner, this);
    }
}
