Implementation library for managing checkpoints with history-based persistence and binary search-based retrieval. Include functions to push new checkpoint values, retrieve latest values, and retrieve values at specific block numbers. Incorporate OpenZeppelin's SafeCast and math library usage for type conversions and mathematical operations. Ensure the contract is callable by any contract and provides clear, well-documented functionality.

```solidity
// SPDX-License-Identifier: MIT
// OpenZeppelin Contracts (last updated v4.5.0) (utils/Checkpoints.sol)
pragma solidity ^0.8.2;
import "./math/Math.sol";
import "./math/SafeCast.sol";
library Checkpoints {
    struct Checkpoint {
        uint32 _blockNumber;
        uint224 _value;
    }
    struct History {
        Checkpoint[] _checkpoints;
    }
    function latest(History storage self) internal view returns (uint256) {
        uint256 pos = self._checkpoints.length;
        return pos == 0 ? 0 : self._checkpoints[pos - 1]._value;
    }
    function getAtBlock(History storage self, uint256 blockNumber) internal view returns (uint256) {
        require(blockNumber < block.number, "Checkpoints: block not yet mined");
        uint256 high = self._checkpoints.length;
        uint256 low = 0;
        while (low < high) {
            uint256 mid = Math.average(low, high);
            if (self._checkpoints[mid]._blockNumber > blockNumber) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return high == 0 ? 0 : self._checkpoints[high - 1]._value;
    }
    function push(History storage self, uint256 value) internal returns (uint256, uint256) {
        uint256 pos = self._checkpoints.length;
        uint256 old = latest(self);
        if (pos > 0 && self._checkpoints[pos - 1]._blockNumber == block.number) {
            self._checkpoints[pos - 1]._value = SafeCast.toUint224(value);
        } else {
            self._checkpoints.push(Checkpoint({_blockNumber: SafeCast.toUint32(block.number), _value: SafeCast.toUint224(value)}));
        }
        return (old, value);
    }
    function push(History storage self,
        function(uint256, uint256) view returns (uint256) op,
        uint256 delta) internal returns (uint256, uint256) {
        return push(self, op(latest(self), delta));
    }
}
