```solidity
// SPDX-License-Identifier: MIT
// OpenZeppelin Contracts v4.4.0 (utils/cryptography/SignatureChecker.sol)
pragma solidity ^0.8.0;
import './ECDSA.sol';
import '../Address.sol';
import '../../interfaces/IERC1271.sol';
library SignatureChecker {
  function isValidSignatureNow(address signer,
    bytes32 hash,
    bytes memory signature) internal view returns (bool) {
    (address recovered, ECDSA.RecoverError error) = ECDSA.tryRecover(hash,
      signature);
    if (error == ECDSA.RecoverError.NoError && recovered == signer) {
      return true;
    }
    (bool success, bytes memory result) = signer.staticcall(abi.encodeWithSelector(IERC1271.isValidSignature.selector,
        hash,
        signature));
    return (success &&
      result.length == 32 &&
      abi.decode(result, (bytes4)) == IERC1271.isValidSignature.selector);
  }
}
