```solidity
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.7;
import "../../base/Sweepableds.sol";
abstract contract MerkleCoreds is Sweepableds {
    function getRootHash(uint256 _index,
        bytes32 _node,
        bytes32[] calldata _merkleProof) internal pure returns (bytes32) {
        uint256 path = _index;
        for (uint256 i = 0; i < _merkleProof.length; i++) {
            if ((path & 0x01) == 1) {
                _node = keccak256(abi.encodePacked(_merkleProof[i], _node));
            } else {
                _node = keccak256(abi.encodePacked(_node, _merkleProof[i]));
            }
            path /= 2;
        }
        return _node;
    }
