Implementation that can be upgraded at runtime. The contract should inherit from the Proxy contract and override the _implementation function. The contract should have a constructor that accepts an address of a new implementation and a bytes array representing data to be passed to the new implementation. The contract should also have a function to upgrade the implementation and emit an event when the implementation is changed.

```solidity
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity ^0.7.0;
import "./Proxy.sol";
import "./Address.sol";
contract UpgradeableProxy is Proxy {
    constructor(address _logic, bytes memory _data) payable {
        assert(_IMPLEMENTATION_SLOT ==
                bytes32(uint256(keccak256("eip1967.proxy.implementation")) - 1));
        _setImplementation(_logic);
        if (_data.length > 0) {
            Address.functionDelegateCall(_logic, _data);
        }
    }
    event Upgraded(address indexed implementation);
    bytes32 private constant _IMPLEMENTATION_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
    function _implementation()
        internal
        view
        virtual
        override
        returns (address impl)
    {
        bytes32 slot = _IMPLEMENTATION_SLOT;
        // solhint-disable-next-line no-inline-assembly
        assembly {
            impl := sload(slot)
        }
    }
    function _upgradeTo(address newImplementation) internal virtual {
        _setImplementation(newImplementation);
        emit Upgraded(newImplementation);
    }
    function _setImplementation(address newImplementation) private {
        require(Address.isContract(newImplementation),
            "UpgradeableProxy: new implementation is not a contract");
        bytes32 slot = _IMPLEMENTATION_SLOT;
        // solhint-disable-next-line no-inline-assembly
        assembly {
            sstore(slot, newImplementation)
        }
    }
}
