Solution for managing storage buckets, incorporating an enum listing predefined storage IDs and a function for retrieving the corresponding storage slot. The contract should utilize bitwise shifting to calculate the storage slot, ensuring efficient storage allocation. Incorporate relevant error handling and cast checks for the storage ID.

```solidity
// SPDX-License-Identifier: Apache-2.0
pragma solidity 0.8.17;
/// @title Common storage helpers
library LibStorage {
    /// @notice What to bit-shift a storage ID by to get its slot.
    ///         This gives us a maximum of 2**128 inline fields in each bucket.
    uint256 private constant STORAGE_SLOT_EXP = 128;
    /// @notice Storage IDs for feature storage buckets.
    ///         WARNING: APPEND-ONLY.
    enum StorageId {
        Proxy,
        SimpleFunctionRegistry,
        Ownable,
        TokenFactory,
        MerkleDistributorFactory,
        MerkleVestingFactory,
        ERC721MerkleDropFactory,
        ERC721CurveFactory,
        ERC721AuctionFactory
    }
    /// @notice Get the storage slot given a storage ID. We assign unique, well-spaced
    ///         slots to storage bucket variables to ensure they do not overlap.
    // solhint-disable-next-line max-line-length
    /// @param storageId An entry in `StorageId`
    /// @return slot The storage slot.
    function getStorageSlot(StorageId storageId) internal pure returns (uint256 slot) {
        // This should never overflow with a reasonable `STORAGE_SLOT_EXP`
        // because Solidity will do a range check on `storageId` during the cast.
        return (uint256(storageId) + 1) << STORAGE_SLOT_EXP;
    }
}
