    // contract for this attack to work.
    function secondPreimageAttack(bytes32 leaf, bytes32[] calldata proof) external {
        bool ok = MerkleProof.verify({proof: proof, root: merkleRoot, leaf: leaf});
        if (!ok) {
            revert InvalidProof();
        }
    }
