Immutable app that allows for the retrieval of current cumulative prices for a Uniswap V2 oracle. The contract should include a library that provides helper methods for oracles to compute average prices. Specifically, it should include the 'currentBlockTimestamp' function to retrieve the current block timestamp, and the 'currentCumulativePrices' function that calculates price0Cumulative and price1Cumulative variables based on the last price data available for a specific pair, handling subtraction overflow in case time has elapsed since the last update.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity >=0.5.0;
import "../../core/interfaces/IUniV2TWAMMPair.sol";
import "../../libraries/FixedPoint.sol";
// library with helper methods for oracles that are concerned with computing average prices
library UniswapV2OracleLibrary {
    using FixedPoint for *;
    function currentBlockTimestamp() internal view returns (uint32) {
        return uint32(block.timestamp % 2**32);
    }
    // produces the cumulative price using counterfactuals to save gas and avoid a call to sync.
    function currentCumulativePrices(address pair)
        internal
        view
        returns (uint256 price0Cumulative,
            uint256 price1Cumulative,
            uint32 blockTimestamp)
    {
        blockTimestamp = currentBlockTimestamp();
        price0Cumulative = IUniV2TWAMMPair(pair).price0CumulativeLast();
        price1Cumulative = IUniV2TWAMMPair(pair).price1CumulativeLast();
        // if time has elapsed since the last update on the pair, mock the accumulated price values
        (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast) = IUniV2TWAMMPair(pair).getReserves();
        if (blockTimestampLast != blockTimestamp) {
            // subtraction overflow is desired
            uint32 timeElapsed = blockTimestamp - blockTimestampLast;
            // addition overflow is desired
            // counterfactual
            price0Cumulative += uint256(FixedPoint.fraction(reserve1, reserve0)._x) * timeElapsed;
            // counterfactual
            price1Cumulative += uint256(FixedPoint.fraction(reserve0, reserve1)._x) * timeElapsed;
        }
    }
}
