```solidity
//SPDX-License-Identifier: Unlicense
pragma solidity 0.8.11;
contract Create3 {
  error ErrorCreatingProxy();
  error ErrorCreatingContract();
  error TargetAlreadyExists();
  bytes internal constant PROXY_CHILD_BYTECODE = hex"67_36_3d_3d_37_36_3d_34_f0_3d_52_60_08_60_18_f3";
  //                        KECCAK256_PROXY_CHILD_BYTECODE = keccak256(PROXY_CHILD_BYTECODE);
  bytes32 internal constant KECCAK256_PROXY_CHILD_BYTECODE = 0x21c35dbe1b344a2488cf3321d6ce542f8e9f305544ff09e4993a62319a497c1f;
  function codeSize(address _addr) internal view returns (uint256 size) {
    assembly { size := extcodesize(_addr) }
  }
  function create3(bytes32 _salt, bytes memory _creationCode) external returns (address addr) {
    return create3(_salt, _creationCode, 0);
  }
  function create3(bytes32 _salt, bytes memory _creationCode, uint256 _value) public returns (address addr) {
    // Creation code
    bytes memory creationCode = PROXY_CHILD_BYTECODE;
    // Get target final address
    addr = addressOf(_salt);
    if (codeSize(addr) != 0) revert TargetAlreadyExists();
    // Create CREATE2 proxy
    address proxy; assembly { proxy := create2(0, add(creationCode, 32), mload(creationCode), _salt)}
    if (proxy == address(0)) revert ErrorCreatingProxy();
    // Call proxy with final init code
    (bool success,) = proxy.call{ value: _value }(_creationCode);
    if (!success || codeSize(addr) == 0) revert ErrorCreatingContract();
  }
  function addressOf(bytes32 _salt) public view returns (address) {
    address proxy = address(uint160(uint256(keccak256(abi.encodePacked(hex'ff',
              address(this),
              _salt,
              KECCAK256_PROXY_CHILD_BYTECODE)))));
    return address(uint160(uint256(keccak256(abi.encodePacked(hex"d6_94",
              proxy,
              hex"01")))));
  }
}
