import {SafeMath} from "./openzeppelin/contracts/math/SafeMath.sol";
import {MathOZ} from "./MathOZ.sol";
library Decimal {
    using SafeMath for uint256;
    // ============ Constants ============
    uint256 constant BASE_POW = 18;
    uint256 constant BASE = 10**BASE_POW;
    // ============ Structs ============
    struct D256 {
        uint256 value;
    }
    // ============ Functions ============
    function one() internal pure returns (D256 memory) {
        return D256({value: BASE});
    }
    function onePlus(D256 memory d) internal pure returns (D256 memory) {
        return D256({value: d.value.add(BASE)});
    }
    function mul(uint256 target, D256 memory d)
        internal
        pure
        returns (uint256)
    {
        return MathOZ.getPartial(target, d.value, BASE);
    }
    function div(uint256 target, D256 memory d)
        internal
        pure
        returns (uint256)
    {
        return MathOZ.getPartial(target, BASE, d.value);
    }
}
