Write a code that implements the EIP712 interface, with a constructor that takes two string parameters (name and version) and generates hashes for the name and version. The contract should include a function to build the domain separator, a function to hash typed data, and a function to retrieve the cached domain separator. Implement the `_buildDomainSeparator` and `_hashTypedDataV4` functions as per EIP712 specification, and ensure that the domain separator is updated when the chain ID changes. The contract should also include a hash for the type, which is statically defined.

```solidity
// SPDX-License-Identifier: MIT
// OpenZeppelin Contracts v4.4.0 (utils/cryptography/draft-EIP712.sol)
pragma solidity ^0.8.0;
import './ECDSA.sol';
abstract contract EIP712 {
  // invalidate the cached domain separator if the chain id changes.
  bytes32 private immutable _CACHED_DOMAIN_SEPARATOR;
  uint256 private immutable _CACHED_CHAIN_ID;
  address private immutable _CACHED_THIS;
  bytes32 private immutable _HASHED_NAME;
  bytes32 private immutable _HASHED_VERSION;
  bytes32 private immutable _TYPE_HASH;
  constructor(string memory name, string memory version) {
    bytes32 hashedName = keccak256(bytes(name));
    bytes32 hashedVersion = keccak256(bytes(version));
    bytes32 typeHash = keccak256('EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)');
    _HASHED_NAME = hashedName;
    _HASHED_VERSION = hashedVersion;
    _CACHED_CHAIN_ID = block.chainid;
    _CACHED_DOMAIN_SEPARATOR = _buildDomainSeparator(typeHash,
      hashedName,
      hashedVersion);
    _CACHED_THIS = address(this);
    _TYPE_HASH = typeHash;
  }
  function _domainSeparatorV4() internal view returns (bytes32) {
    if (address(this) == _CACHED_THIS && block.chainid == _CACHED_CHAIN_ID) {
      return _CACHED_DOMAIN_SEPARATOR;
    } else {
      return _buildDomainSeparator(_TYPE_HASH, _HASHED_NAME, _HASHED_VERSION);
    }
  }
  function _buildDomainSeparator(bytes32 typeHash,
    bytes32 nameHash,
    bytes32 versionHash) private view returns (bytes32) {
    return
      keccak256(abi.encode(typeHash,
          nameHash,
          versionHash,
          block.chainid,
          address(this)));
  }
  function _hashTypedDataV4(bytes32 structHash)
    internal
    view
    virtual
    returns (bytes32)
  {
    return ECDSA.toTypedDataHash(_domainSeparatorV4(), structHash);
  }
}
