contract RefundEscrow is ConditionalEscrow {
    using Address for address payable;
    enum State {
        Active,
        Refunding,
        Closed
    }
    event RefundsClosed();
    event RefundsEnabled();
    State private _state;
    address payable private immutable _beneficiary;
