Algorithm code that implements a 'PrivacyFactory' contract, which inherits from the 'Level' contract and imports 'BaseLevel.sol' and 'Privacy.sol'. The contract should have two functions: 'createInstance' that creates a new instance of 'Privacy' contract and returns its address, and 'validateInstance' that validates the created instance by checking if it's not locked. The 'createInstance' function should generate a unique key for each instance using keccak256 hashing and encoding the transaction origin. The contract should be compatible with Solidity version 0.8.14.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.14;
import '../BaseLevel.sol';
import './Privacy.sol';
contract PrivacyFactory is Level {
  function createInstance(address) override public payable returns (address) {
    bytes32[3] memory data;
    data[0] = keccak256(abi.encodePacked(tx.origin,"0"));
    data[1] = keccak256(abi.encodePacked(tx.origin,"1"));
    data[2] = keccak256(abi.encodePacked(tx.origin,"2"));
    Privacy instance = new Privacy(data);
    return address(instance);
  }
  function validateInstance(address payable _instance, address) override public returns (bool) {
    Privacy instance = Privacy(_instance);
    return instance.locked() == false;
  }
}
