Ethereum component that utilizes the Merkle proof verification function to validate the integrity of cryptocurrency wallet addresses. The function should take three parameters: a bytes32 leaf value representing the wallet address, a bytes32 root value representing the Merkle proof's root hash, and a bytes array proof parameter containing the proof elements. The contract should adhere to the Ethereum 0.4.18 compiler version and include detailed logging and error handling for any potential errors or invalid inputs.

```solidity
pragma solidity 0.4.18;
library MerkleProof {
  function verifyProof(bytes _proof, bytes32 _root, bytes32 _leaf) public pure returns (bool) {
    // Check if proof length is a multiple of 32
    if (_proof.length % 32 != 0) return false;
    bytes32 proofElement;
    bytes32 computedHash = _leaf;
    for (uint256 i = 32; i <= _proof.length; i += 32) {
      assembly {
        // Load the current element of the proof
        proofElement := mload(add(_proof, i))
      }
      if (computedHash < proofElement) {
        // Hash(current computed hash + current element of the proof)
        computedHash = keccak256(computedHash, proofElement);
      } else {
        // Hash(current element of the proof + current computed hash)
        computedHash = keccak256(proofElement, computedHash);
      }
    }
    // Check if the computed hash (root) is equal to the provided root
    return computedHash == _root;
  }
}
