I would like to provision a framework that implements a proxy contract with upgradeability, allowing the upgrade of the logic implementation while preserving the existing state. The contract should include a constructor that initializes the implementation, an event for upgrade notifications, a function for upgrading the implementation, and a function for setting the implementation. Additionally, the contract should override the _implementation function to return the current implementation. The implementation should be stored in a slot in the EIP1967 implementation format.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity 0.7.6;
import './Proxy.sol';
import '@openzeppelin/contracts/utils/Address.sol';
contract UpgradeabilityProxy is Proxy {
  constructor(address _logic, bytes memory _data) payable {
    assert(IMPLEMENTATION_SLOT == bytes32(uint256(keccak256('eip1967.proxy.implementation')) - 1));
    _setImplementation(_logic);
    if(_data.length > 0) {
      (bool success,) = _logic.delegatecall(_data);
      require(success);
    }
  }  
  event Upgraded(address indexed implementation);
  bytes32 internal constant IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
  function _implementation() internal override view returns (address impl) {
    bytes32 slot = IMPLEMENTATION_SLOT;
    assembly {
      impl := sload(slot)
    }
  }
  function _upgradeTo(address newImplementation) internal {
    _setImplementation(newImplementation);
    emit Upgraded(newImplementation);
  }
  function _setImplementation(address newImplementation) internal {
    require(Address.isContract(newImplementation), "Cannot set a proxy implementation to a non-contract address");
    bytes32 slot = IMPLEMENTATION_SLOT;
    assembly {
      sstore(slot, newImplementation)
    }
  }
}
