Create a code that allows a controller address to update the implementation address stored in storage slot zero. The contract should have a single function that accepts a new implementation address and stores it in storage slot zero. The function should return the current implementation address for all callers other than the controller. The implementation should be loaded from storage slot zero and returned to non-controller callers. The controller should be able to set a new implementation address by sending a transaction with the new address as the function's calldata. The contract should use the `assembly` keyword to interact with storage slot zero.

```solidity
pragma solidity 0.5.11;
contract DharmaUpgradeBeacon {
  // The implementation address is held in storage slot zero.
  address private _implementation;
  // The controller that can update the implementation is set as a constant.
  address private constant _CONTROLLER = address(0x00000000002226C940b74d674B85E4bE05539663);
  function () external {
    // Return implementation address for all callers other than the controller.
    if (msg.sender != _CONTROLLER) {
      // Load implementation from storage slot zero into memory and return it.
      assembly {
        mstore(0, sload(0))
        return(0, 32)
      }
    } else {
      // Set implementation - put first word in calldata in storage slot zero.
      assembly { sstore(0, calldataload(0)) }
    }
  }
}
